<?php require_once __DIR__ . '/includes/toast.php'; ?>
<script>
(function(){'use strict';var api='api/business-profile.php';
function toast(t,m){if(window.fieldplxToast)fieldplxToast(t,m);else alert(m)}
function postForm(form,extra){var fd=new FormData(form);if(extra)Object.keys(extra).forEach(function(k){fd.set(k,extra[k]);});return fetch(api,{method:'POST',body:fd,headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(r){return r.json().catch(function(){return {success:false,message:'Invalid server response.'};}).then(function(d){if(!r.ok||!d.success)throw new Error(d.message||'Unable to save.');return d;});});}
document.querySelectorAll('.ajax-form').forEach(function(form){form.addEventListener('submit',function(e){e.preventDefault();var btn=form.querySelector('[type=submit]');if(btn)btn.disabled=true;postForm(form).then(function(d){toast('success',d.message);if(form.dataset.formType==='save_brand_colors')form.querySelectorAll('input[type=color]').forEach(function(i){var s=i.closest('.color-row').querySelector('.color-meta span');if(s)s.textContent=i.value.toUpperCase();});}).catch(function(err){toast('error',err.message);}).finally(function(){if(btn)btn.disabled=false;});});});
document.querySelectorAll('[data-reset-form]').forEach(function(b){b.addEventListener('click',function(){b.closest('form').reset();});});
document.querySelectorAll('.countable').forEach(function(t){t.addEventListener('input',function(){var c=t.parentNode.querySelector('.bp-count span');if(c)c.textContent=t.value.length;});});
document.querySelectorAll('.bp-accordion-btn').forEach(function(b){b.addEventListener('click',function(){var s=b.nextElementSibling;var open=s.style.display!=='none';s.style.display=open?'none':'block';b.lastElementChild.textContent=open?'⌄':'⌃';});});
var consent=document.getElementById('aiConsent'),gen=document.getElementById('generateAiBtn');if(consent&&gen){consent.addEventListener('change',function(){gen.disabled=!consent.checked;});gen.addEventListener('click',function(){toast('warning','AI content generation requires your configured AI service. The Business Profile fields are ready for that integration.');});}
var legalModal=document.getElementById('legalModal'),legalTitle=document.getElementById('legalTitle'),legalType=document.getElementById('legalType'),legalUrl=document.getElementById('legalUrl'),legalHelp=document.getElementById('legalHelp');
function closeModals(){document.querySelectorAll('.bp-modal-bg').forEach(function(m){m.classList.remove('open');});}
document.querySelectorAll('[data-close-modal]').forEach(function(b){b.addEventListener('click',closeModals);});document.querySelectorAll('.bp-modal-bg').forEach(function(m){m.addEventListener('click',function(e){if(e.target===m)closeModals();});});document.addEventListener('keydown',function(e){if(e.key==='Escape')closeModals();});
var legalValues={terms:<?=json_encode((string)$profile['terms_url'])?>,privacy:<?=json_encode((string)$profile['privacy_url'])?>};document.querySelectorAll('[data-legal]').forEach(function(b){b.addEventListener('click',function(){var type=b.dataset.legal;legalType.value=type;legalUrl.value=legalValues[type]||'';legalTitle.textContent=type==='terms'?'Edit Terms and Conditions':'Edit Privacy Policy';legalHelp.textContent=type==='terms'?'Add a link to the terms and conditions your customers agree to when they work with you.':'Add a link to your privacy policy so customers can see how you collect and use their information.';legalModal.classList.add('open');});});
document.getElementById('legalForm').addEventListener('submit',function(e){e.preventDefault();var form=e.currentTarget;postForm(form).then(function(d){var type=legalType.value;legalValues[type]=legalUrl.value;var s=document.getElementById(type+'Status');if(s)s.textContent=legalUrl.value||('Add a link to your '+(type==='terms'?'terms and conditions.':'privacy policy.'));toast('success',d.message);closeModals();}).catch(function(err){toast('error',err.message);});});
var logoInput=document.getElementById('logoInput');document.getElementById('logoSelectBtn').addEventListener('click',function(){logoInput.click();});logoInput.addEventListener('change',function(){if(!logoInput.files.length)return;var fd=new FormData();fd.append('csrf_token',<?=json_encode($csrfToken)?>);fd.append('action','upload_logo');fd.append('logo',logoInput.files[0]);fetch(api,{method:'POST',body:fd,headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(r){return r.json().then(function(d){if(!r.ok||!d.success)throw new Error(d.message||'Upload failed.');return d;});}).then(function(d){document.getElementById('logoBox').innerHTML='<img src="'+d.logo_path+'?v='+Date.now()+'" alt="Company logo">';toast('success',d.message);}).catch(function(err){toast('error',err.message);});});
var rm=document.getElementById('removeLogoBtn');if(rm)rm.addEventListener('click',function(){var fd=new FormData();fd.append('csrf_token',<?=json_encode($csrfToken)?>);fd.append('action','remove_logo');fetch(api,{method:'POST',body:fd,headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(r){return r.json().then(function(d){if(!r.ok||!d.success)throw new Error(d.message);return d;});}).then(function(d){document.getElementById('logoBox').innerHTML='<span>No logo</span>';toast('success',d.message);rm.remove();}).catch(function(err){toast('error',err.message);});});
var docModal=document.getElementById('docModal');document.getElementById('openDocSettings').addEventListener('click',function(){docModal.classList.add('open');});document.querySelectorAll('.doc-tab').forEach(function(tab){tab.addEventListener('click',function(){document.querySelectorAll('.doc-tab').forEach(function(t){t.classList.remove('active');});document.querySelectorAll('.doc-pane').forEach(function(p){p.classList.remove('active');});tab.classList.add('active');var pane=document.querySelector('[data-doc-pane="'+tab.dataset.docTab+'"]');if(pane)pane.classList.add('active');var title=document.querySelector('.paper-title');if(title)title.textContent=(tab.dataset.docTab==='job'?'Job #2':tab.dataset.docTab==='invoice'?'Invoice #2':'Quote #4');});});
var estimate=document.getElementById('estimateToggle'),quoteLabel=document.getElementById('quoteLabel');if(estimate)estimate.addEventListener('change',function(){quoteLabel.value=estimate.checked?'Estimate':'Quote';});document.querySelectorAll('[data-preview-pdf]').forEach(function(b){b.addEventListener('click',function(){toast('info','Preview reflects the selected document settings in the panel. Connect your existing PDF template to use these saved values for final PDFs.');});});
})();
</script>
